// RunMachineSuite applies the checks of Machine, and the checks that opts
// add, to a fresh subject of newSubject for each check.
func RunMachineSuite[T MachineMethods](t *testing.T, newSubject func() T, opts ...MachineOption) {
	t.Helper()
	RunMachineSuiteFromHandle(t, func(*MachineHandle) T { return newSubject() }, opts...)
}

// RunMachineSuiteFromHandle applies the same checks to a subject that
// newSubject builds from the handle of each check.
func RunMachineSuiteFromHandle[T MachineMethods](
	t *testing.T,
	newSubject func(h *MachineHandle) T,
	opts ...MachineOption,
) {
	t.Helper()
	conform.Run(t, MachineSuite(), machineSubjects(newSubject), opts...)
}

// FuzzMachineSuite registers on f the fuzz target of the property checks
// of callable, on a subject that newSubject builds from the handle of each
// case.
func FuzzMachineSuite[T MachineMethods](
	f *testing.F,
	callable conform.Callable[MachineMethods],
	newSubject func(h *MachineHandle) T,
	opts ...MachineOption,
) {
	f.Helper()
	conform.Fuzz(f, MachineSuite(), callable, machineSubjects(newSubject), opts...)
}

// RunMachineBudgets applies the allocation ceilings of Machine and its
// checks that count allocations, and the ceilings and the checks that opts
// add, to a fresh subject of newSubject for each case.
func RunMachineBudgets[T MachineMethods](t *testing.T, newSubject func(h *MachineHandle) T, opts ...MachineOption) {
	t.Helper()
	conform.RunBudgets(t, MachineSuite(), machineSubjects(newSubject), opts...)
}

